class SharedQueue {
    private final List<String> queue = new ArrayList<>();
    private final int capacity = 5;

    public synchronized void produce(String item) throws InterruptedException {
        while (queue.size() == capacity) {
            wait(); // release lock and wait for space
        }
        queue.add(item);
        System.out.println("Produced: " + item);
        notifyAll(); // wake up consumers
    }

    public synchronized String consume() throws InterruptedException {
        while (queue.isEmpty()) {
            wait(); // release lock and wait for items
        }
        var item = queue.remove(0);
        System.out.println("Consumed: " + item);
        notifyAll(); // wake up producers
        return item;
    }
}

class BrokenQueue {
    private boolean isEmpty = true;

    // BAD: not synchronized
    public void consume() throws InterruptedException {
        if (isEmpty) {
            // RACE WINDOW: another thread could produce() and notify() here
            wait(); // throws IllegalMonitorStateException
        }
    }

    // CORRECT: synchronized ensures atomicity
    public synchronized void consumeCorrect() throws InterruptedException {
        while (isEmpty) {
            wait(); // atomically releases monitor and waits
        }
        // consume logic
        isEmpty = true;
    }

    public synchronized void produce() {
        isEmpty = false;
        notifyAll();
    }
}

class MessageQueue {
    private String message = null;

    // WRONG: if statement allows spurious wakeup bug
    public synchronized String receiveBuggy() throws InterruptedException {
        if (message == null) {
            wait(); // spurious wakeup returns here
        }
        return message; // NPE if wakeup was spurious!
    }

    // CORRECT: while loop handles spurious wakeups
    public synchronized String receive() throws InterruptedException {
        while (message == null) {
            wait(); // re-checks condition on any wakeup
        }
        var msg = message;
        message = null;
        notifyAll();
        return msg;
    }

    public synchronized void send(String msg) {
        message = msg;
        notifyAll();
    }
}

class BankAccount {
    private double balance = 0;
    private final Object lockObject = new Object();

    public void deposit(double amount) {
        synchronized (lockObject) { // any object can be a lock
            balance += amount;
            lockObject.notifyAll(); // wake threads waiting on this lock
        }
    }

    public void waitForBalance(double target) throws InterruptedException {
        synchronized (lockObject) {
            while (balance < target) {
                lockObject.wait(); // wait on the same object we locked
            }
        }
    }
}

// Even a String can be a lock
var sharedLock = "myLock";
synchronized (sharedLock) {
    sharedLock.wait(); // works because String extends Object
}
